cards.extra_styles:
@keyframes flamePulse{
  0%,100%{transform:translate(-50%,0) scale(.92);filter:drop-shadow(0 0 7px rgba(255,126,48,.62))}
  50%{transform:translate(-50%,-2px) scale(1.08);filter:drop-shadow(0 0 16px rgba(255,160,69,.96))}
}
@keyframes bubbleRise{
  0%{transform:translateY(18px) scale(.72);opacity:0}
  18%{opacity:.72}
  100%{transform:translateY(-55px) scale(1.05);opacity:0}
}
@keyframes waterDrift{
  0%{transform:translateX(-6%)}
  50%{transform:translateX(6%)}
  100%{transform:translateX(-6%)}
}
@keyframes flowLeft{
  0%{transform:translateX(0);opacity:.08}
  30%{opacity:.9}
  100%{transform:translateX(120px);opacity:.08}
}
@keyframes flowRight{
  0%{transform:translateX(0);opacity:.08}
  30%{opacity:.9}
  100%{transform:translateX(-120px);opacity:.08}
}
@keyframes pumpSpin{
  from{transform:translate(-50%,-50%) rotate(0deg)}
  to{transform:translate(-50%,-50%) rotate(360deg)}
}
@keyframes pumpGlow{
  0%,100%{box-shadow:0 0 7px rgba(77,216,201,.20),inset 0 0 9px rgba(76,211,198,.08)}
  50%{box-shadow:0 0 14px rgba(77,216,201,.55),inset 0 0 13px rgba(76,211,198,.16)}
}

.boiler-scene{
  position:relative;height:246px;width:100%;overflow:visible;display:flex;align-items:center;justify-content:center
}

.boiler-shell{
  position:relative;width:154px;height:190px;border-radius:18px 18px 14px 14px;
  background:linear-gradient(180deg,rgba(29,53,68,.90),rgba(9,20,29,.94)),rgba(8,18,26,.94);
  border:1px solid rgba(102,204,246,.54);
  box-shadow:0 0 18px rgba(62,182,232,.16),inset 0 0 26px rgba(67,178,220,.08),inset 0 1px 0 rgba(255,255,255,.06)
}
.boiler-shell:before{
  content:'';position:absolute;inset:7px;border-radius:13px;border:1px solid rgba(126,210,244,.10);pointer-events:none
}
.burning .boiler-shell{
  border-color:rgba(117,211,247,.60);
  box-shadow:0 0 20px rgba(62,182,232,.18),0 12px 26px -23px rgba(255,129,56,.88),inset 0 0 26px rgba(67,178,220,.09)
}

.boiler-top{
  position:absolute;top:12px;left:23px;right:23px;height:8px;display:flex;gap:6px;justify-content:center;opacity:.65
}
.boiler-top span{
  width:14px;height:2px;border-radius:2px;background:linear-gradient(90deg,transparent,#6ab9de,transparent);box-shadow:0 0 5px rgba(86,190,235,.30)
}

.service-display{
  position:absolute;top:22px;left:50%;transform:translateX(-50%);
  width:40px;height:15px;border-radius:5px;
  border:1px solid rgba(97,183,221,.24);
  background:linear-gradient(180deg,rgba(7,18,25,.94),rgba(12,29,39,.92));
  box-shadow:inset 0 0 9px rgba(65,163,207,.08),0 0 8px rgba(50,157,205,.07);
  display:flex;align-items:center;justify-content:center
}
.service-code{
  font-family:monospace;font-size:8px;letter-spacing:1.1px;color:#7fd2f1;
  text-shadow:0 0 6px rgba(89,199,241,.35)
}

.status-led{
  position:absolute;right:15px;top:32px;width:5px;height:5px;border-radius:50%;
  background:#55d8b7;box-shadow:0 0 8px rgba(85,216,183,.72)
}
.burning .status-led{background:#ff9d58;box-shadow:0 0 9px rgba(255,157,88,.80)}

.display-window{
  position:absolute;left:20px;right:20px;top:48px;height:70px;border-radius:12px;
  overflow:hidden;border:1px solid rgba(108,204,245,.30);
  background:linear-gradient(180deg,rgba(28,69,92,.56),rgba(21,55,76,.30));
  box-shadow:inset 0 0 22px rgba(63,174,222,.10),0 0 12px rgba(49,166,217,.07)
}
.water-layer{
  position:absolute;left:0;right:0;bottom:0;height:58%;
  background:linear-gradient(180deg,rgba(63,183,230,.05),rgba(42,143,197,.21));
  overflow:hidden
}
.water-layer:before{
  content:'';position:absolute;left:-12%;right:-12%;top:-8px;height:17px;border-radius:50%;
  border-top:1px solid rgba(124,226,255,.46);box-shadow:0 -1px 8px rgba(88,202,242,.18);
  animation:waterDrift 3.2s ease-in-out infinite
}

.temp-main{
  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  font-size:24px;font-weight:300;letter-spacing:-.9px;color:#e4f8ff;text-shadow:0 0 14px rgba(86,206,247,.30)
}
.temp-label{
  position:absolute;left:0;right:0;bottom:7px;text-align:center;
  font-size:6px;text-transform:uppercase;letter-spacing:.7px;color:#78a9be
}

.bubble{
  position:absolute;bottom:1px;width:5px;height:5px;border-radius:50%;border:1px solid rgba(201,243,255,.64);opacity:0
}
.pumping .bubble,.burning .bubble{animation:bubbleRise 2.3s linear infinite}
.b1{left:25%;animation-delay:.15s!important}
.b2{left:44%;width:4px;height:4px;animation-delay:.72s!important}
.b3{left:63%;width:6px;height:6px;animation-delay:1.24s!important}
.b4{left:77%;width:3px;height:3px;animation-delay:1.68s!important}

.burner-zone{
  position:absolute;left:26px;bottom:22px;width:42px;height:36px;border-radius:10px;
  background:linear-gradient(180deg,rgba(255,255,255,.025),rgba(255,255,255,.012));
  border:1px solid rgba(255,255,255,.055)
}
.flame{
  position:absolute;left:50%;top:4px;transform:translateX(-50%);
  width:27px;height:27px;color:#5a6870;opacity:.20
}
.burning .flame{color:#ff914a;opacity:1;animation:flamePulse 1.15s ease-in-out infinite}

.pump-zone{
  position:absolute;right:24px;bottom:20px;width:44px;height:40px;display:flex;align-items:center;justify-content:center
}
.pump-ring{
  position:absolute;top:3px;left:7px;width:29px;height:29px;border-radius:50%;
  border:1px solid rgba(103,145,160,.30);
  background:radial-gradient(circle at 50% 50%,rgba(255,255,255,.025),rgba(10,25,34,.65));
  box-shadow:inset 0 0 8px rgba(73,122,143,.06)
}
.pump-ring:before,.pump-ring:after{
  content:'';position:absolute;top:12px;width:6px;height:4px;border-top:1px solid rgba(94,153,176,.25);border-bottom:1px solid rgba(94,153,176,.13)
}
.pump-ring:before{left:-6px}
.pump-ring:after{right:-6px}
.pump-rotor{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  width:18px;height:18px;color:#657c88;opacity:.36
}
.pumping .pump-ring{
  border-color:rgba(91,224,207,.58);
  background:radial-gradient(circle at 50% 50%,rgba(60,214,198,.10),rgba(10,32,38,.68));
  animation:pumpGlow 1.7s ease-in-out infinite
}
.pumping .pump-rotor{
  color:#68dfcb;opacity:1;filter:drop-shadow(0 0 5px rgba(94,229,211,.65));
  animation:pumpSpin .92s linear infinite;transform-origin:50% 50%
}

.service-strip{
  position:absolute;left:62px;right:62px;bottom:8px;height:3px;display:flex;gap:4px;justify-content:center
}
.service-strip span{width:4px;height:2px;border-radius:2px;background:#4a6d7e}

.pipe{
  position:absolute;top:99px;height:2px;z-index:-1;
  background:linear-gradient(90deg,rgba(64,140,179,.02),rgba(90,203,247,.64),rgba(64,140,179,.02));
  box-shadow:0 0 9px rgba(80,194,239,.22)
}
.pipe-left{left:5%;right:calc(50% + 88px)}
.pipe-right{right:5%;left:calc(50% + 88px)}
.pumping .pipe{box-shadow:0 0 12px rgba(80,194,239,.38)}

.flow-pulse{
  display:none;position:absolute;top:95.5px;width:8px;height:8px;border-radius:50%;background:#7bdbff;box-shadow:0 0 12px rgba(89,214,255,.92)
}
.pumping .flow-pulse{display:block}
.fp1{left:7%;animation:flowLeft 1.7s linear infinite}
.fp2{right:7%;animation:flowRight 1.7s linear infinite;animation-delay:.78s}

.outlet-label{
  position:absolute;left:calc(50% + 84px);top:91px;
  min-width:auto;padding:0 2px;
  background:transparent;border:none;box-shadow:none;
  text-align:left;pointer-events:none
}
.outlet-value{
  display:block;font-size:12px;font-weight:650;color:#9adbf6;line-height:1;
  text-shadow:0 0 7px rgba(95,201,244,.24)
}
.outlet-caption{display:none}

/* HEATING_GEOMETRY_AUDIT_20260928 */
/* Přívod + zpátečka jsou ukotvené do dvou samostatných horních přípojek. */
.boiler-shell:after{display:none!important}
.boiler-top:before,
.boiler-top:after{
  content:'';
  position:absolute;
  top:-21px;
  width:5px;
  height:12px;
  border-radius:3px 3px 1px 1px;
  box-sizing:border-box;
  z-index:-1;
}
.boiler-top:before{
  left:calc(50% - 8.5px);
  background:linear-gradient(90deg,rgba(13,33,43,.98),rgba(76,159,188,.82),rgba(13,33,43,.98));
  border:1px solid rgba(109,207,239,.42);
  box-shadow:0 -2px 9px rgba(80,194,239,.20);
}
.boiler-top:after{
  left:calc(50% + 3.5px);
  background:linear-gradient(90deg,rgba(10,27,35,.98),rgba(55,111,130,.80),rgba(10,27,35,.98));
  border:1px solid rgba(82,151,176,.34);
  box-shadow:0 -2px 7px rgba(66,137,162,.14);
}
.pumping .boiler-top:before{
  border-color:rgba(129,224,251,.66);
  box-shadow:0 -2px 12px rgba(80,194,239,.38);
}
.pumping .boiler-top:after{
  border-color:rgba(91,169,195,.58);
  box-shadow:0 -2px 10px rgba(66,151,179,.27);
}
/* Původní boční dekorativní trubky nebyly součástí skutečného schématu. */
.pipe,.flow-pulse{display:none!important}


/* OUTLET_LABEL_REALIGN_20260928 */
.outlet-label{
  left:calc(50% + 16px)!important;
  top:9px!important;
  padding:0 2px!important;
  text-align:left!important;
}
.outlet-value{
  font-size:11px!important;
  color:#9adbf6!important;
  text-shadow:0 0 7px rgba(95,201,244,.24)!important;
}


/* FINAL_BOILER_CONNECTION_CLEANUP_20260928 */
/* Finální spoj: dvě SVG trubky končí přímo na horní hraně kotle. */
.boiler-top:before,
.boiler-top:after{
  display:none!important;
}


/* UNIFIED_HYDRAULICS_20260928 */
.boiler-shell:after,
.boiler-top:before,
.boiler-top:after,
.pipe,
.flow-pulse{
  display:none!important;
}


/* FINAL_HYDRAULIC_PORTS_20260928 */
/* Dva fyzické porty kotle přesně pod osami přívodu/zpátečky.
   Boiler scene má šířku 738 px; osy jsou ±13 px od středu. */
.boiler-scene{
  isolation:isolate;
}
.boiler-shell{
  z-index:1;
}
.boiler-scene::before,
.boiler-scene::after{
  content:'';
  position:absolute;
  top:16px;
  width:6px;
  height:12px;
  border-radius:3px 3px 1px 1px;
  box-sizing:border-box;
  z-index:0;
  pointer-events:none;
}
.boiler-scene::before{
  left:calc(50% - 16px);
  background:linear-gradient(90deg,#0d2631,#4d98b4,#0d2631);
  border:1px solid rgba(112,205,238,.46);
  box-shadow:0 -2px 8px rgba(82,190,232,.18);
}
.boiler-scene::after{
  left:calc(50% + 10px);
  background:linear-gradient(90deg,#0a2029,#355f70,#0a2029);
  border:1px solid rgba(77,143,168,.34);
  box-shadow:0 -2px 6px rgba(57,132,160,.12);
}
.boiler-scene.pumping::before{
  border-color:rgba(132,227,252,.72);
  box-shadow:0 -2px 11px rgba(86,204,244,.40);
}
.boiler-scene.pumping::after{
  border-color:rgba(93,170,196,.60);
  box-shadow:0 -2px 9px rgba(65,151,180,.25);
}

/* Výstupní teplota patří k přívodní stoupačce. */
.outlet-label{
  left:calc(50% - 73px)!important;
  top:5px!important;
  min-width:64px!important;
  padding:0!important;
  text-align:right!important;
}
.outlet-value{
  font-size:10px!important;
  font-weight:650!important;
  color:#9adbf6!important;
  letter-spacing:.05px!important;
  text-shadow:0 0 7px rgba(95,201,244,.22)!important;
}
.outlet-value::before{
  content:'Výstup ';
  font-size:7px;
  font-weight:550;
  color:#6f9bab;
  letter-spacing:.15px;
}

/* Staré pseudo-trubky a dekorativní boční vedení zůstávají vypnuté. */
.boiler-shell:after,
.boiler-top:before,
.boiler-top:after,
.pipe,
.flow-pulse{
  display:none!important;
}


/* SVG_PORTS_FINAL_20260928 */
/* Porty jsou nyní kreslené přímo v unified SVG, ne přes CSS pseudo-elementy. */
.boiler-scene::before,
.boiler-scene::after{
  display:none!important;
}

custom_fields.hydraulics:
[[[
      const pump=states['binary_sensor.boiler_heatingpump']?.state==='on';
      const burn=states['binary_sensor.boiler_burngas']?.state==='on';

      const sx=356;
      const rx=382;
      const crossGap=2;

      const zones=[
        {e:'binary_sensor.zona_2p_mama_aktivni',               c:480, top:126, sy:142, ry:144},
        {e:'binary_sensor.zona_1p_jidelna_aktivni',            c:82,  top:251, sy:253, ry:255},
        {e:'binary_sensor.zona_1p_kuchyn_aktivni',             c:258, top:251, sy:259, ry:261},
        {e:'binary_sensor.zona_1p_chodba_aktivni',             c:480, top:251, sy:265, ry:267},
        {e:'binary_sensor.zona_1p_koupelna_aktivni',           c:656, top:251, sy:271, ry:273},
        {e:'binary_sensor.zona_prizemi_michal_aktivni',        c:258, top:382, sy:390, ry:392},
        {e:'binary_sensor.zona_prizemi_chodba_zachod_aktivni', c:480, top:382, sy:400, ry:402},
        {e:'binary_sensor.zona_sklep_michal_aktivni',          c:258, top:498, sy:510, ry:512}
      ];

      const supplyBase='#314b58';
      const returnBase='#20323b';
      const supplyReq='#507d91';
      const returnReq='#375a68';
      const supplyFlow=burn?'#7bcbe2':'#69b5cd';
      const returnFlow='#4b8194';

      // Čisté křížení: jen krátká mezera v horizontální trase,
      // žádný oblouk, žádný falešný uzel.
      const supplyVisible=z=>{
        const end=z.c-4;
        if(z.c>rx){
          return 'M '+sx+' '+z.sy+
                 ' H '+(rx-crossGap)+
                 ' M '+(rx+crossGap)+' '+z.sy+
                 ' H '+end+' V '+z.top;
        }
        return 'M '+sx+' '+z.sy+' H '+end+' V '+z.top;
      };

      const returnVisible=z=>{
        const start=z.c+4;
        if(z.c<sx){
          return 'M '+start+' '+z.top+
                 ' V '+z.ry+
                 ' H '+(sx-crossGap)+
                 ' M '+(sx+crossGap)+' '+z.ry+
                 ' H '+rx;
        }
        return 'M '+start+' '+z.top+' V '+z.ry+' H '+rx;
      };

      const supplyMotion=z=>'M '+sx+' '+z.sy+' H '+(z.c-4)+' V '+z.top;
      const returnMotion=z=>'M '+(z.c+4)+' '+z.top+' V '+z.ry+' H '+rx;

      let base='';
      let active='';

      zones.forEach((z,i)=>{
        const sp=supplyVisible(z);
        const rp=returnVisible(z);

        base+='<path d="'+sp+'" stroke="'+supplyBase+'" stroke-width=".78" stroke-linecap="round" stroke-linejoin="round" fill="none" opacity=".76"/>';
        base+='<path d="'+rp+'" stroke="'+returnBase+'" stroke-width=".48" stroke-linecap="round" stroke-linejoin="round" fill="none" opacity=".54"/>';

        const request=states[z.e]?.state==='on';
        if(request){
          const sc=pump?supplyFlow:supplyReq;
          const rc=pump?returnFlow:returnReq;

          active+='<path d="'+sp+'" stroke="'+sc+'" stroke-width="'+(pump?'1.30':'1.02')+'" stroke-linecap="round" stroke-linejoin="round" fill="none"/>';
          active+='<path d="'+rp+'" stroke="'+rc+'" stroke-width="'+(pump?'.86':'.68')+'" stroke-linecap="round" stroke-linejoin="round" fill="none"/>';

          if(pump){
            const dur=(1.42+(i%3)*.12).toFixed(2);
            const delay=((i%4)*.15).toFixed(2);

            active+='<circle r="1.66" fill="#a5ebfc">'+
              '<animateMotion dur="'+dur+'s" begin="'+delay+'s" repeatCount="indefinite" path="'+supplyMotion(z)+'"/>'+
            '</circle>';

            active+='<circle r="1.16" fill="#70aabd">'+
              '<animateMotion dur="'+dur+'s" begin="'+(Number(delay)+.34).toFixed(2)+'s" repeatCount="indefinite" path="'+returnMotion(z)+'"/>'+
            '</circle>';
          }
        }
      });

      const supplyRiserDot=pump
        ?'<circle r="1.54" fill="#a5ebfc"><animateMotion dur="2.30s" repeatCount="indefinite" path="M '+sx+' 592 V38"/></circle>'
        :'';

      const returnRiserDot=pump
        ?'<circle r="1.08" fill="#70aabd"><animateMotion dur="2.50s" begin=".46s" repeatCount="indefinite" path="M '+rx+' 38 V592"/></circle>'
        :'';

      const supplyPort=pump?supplyFlow:'#3d6b7d';
      const returnPort=pump?returnFlow:'#2f5361';

      return '<svg viewBox="0 0 738 810" width="738" height="810" xmlns="http://www.w3.org/2000/svg">'+
        '<path d="M'+sx+' 36 V580" stroke="'+supplyBase+'" stroke-width=".96" stroke-linecap="round" fill="none" opacity=".86"/>'+
        '<path d="M'+rx+' 36 V580" stroke="'+returnBase+'" stroke-width=".56" stroke-linecap="round" fill="none" opacity=".64"/>'+
        base+active+supplyRiserDot+returnRiserDot+
        // Porty jsou ve STEJNÉM SVG jako stoupačky: 580 -> 592 (horní hrana shellu po započtení 12px grid gap).
        '<path d="M'+sx+' 580 V592" stroke="'+supplyPort+'" stroke-width="5" stroke-linecap="round" fill="none"/>'+
        '<path d="M'+rx+' 580 V592" stroke="'+returnPort+'" stroke-width="4" stroke-linecap="round" fill="none"/>'+
      '</svg>';
    ]]]

cards.content:
{% set active=state_attr('sensor.heating_schedule_windows','active_helpers') or [] %}
{% set zones=['sklep_michal','prizemi_michal','prizemi_chodba_zachod','1p_jidelna','1p_kuchyn','1p_koupelna','1p_chodba','2p_mama'] %}
{% set ns=namespace(manual=0,enabled=0) %}
{% for z in zones %}
  {% if is_state('input_boolean.schedule_enable_'~z,'on') %}{% set ns.enabled=ns.enabled+1 %}{% endif %}
  {% if is_state('input_boolean.'~z~'_manual_override','on') %}{% set ns.manual=ns.manual+1 %}{% endif %}
{% endfor %}
## {{ states('input_select.topny_rezim') if states('input_select.topny_rezim') in ['Auto','Eco','Boost','Off'] else 'Režim neznámý' }}
**{{ active|length }}/8** zón je právě v komfortním okně · **{{ ns.enabled }}/8** rozvrhů povoleno{% if ns.manual %} · **{{ ns.manual }}** ruční {{ 'zásah' if ns.manual==1 else 'zásahy' }}{% endif %}

<small>Globální nastavení je hned pod tímto přehledem. Jednotlivé místnosti jsou řazené podle podlaží.</small>

