/* HEATING_STATUS_CLEAR_20260918 — display only */
${(() => {
  const getStatus = /* Display only. Uses the same effective override priority as central dispatch.
 * zone_*_aktivni is the zone request, not boiler relay or burner feedback. */
function zoneStatus(hass, entity) {
  const states = hass.states;
  const z = entity.split('.')[1];
  const e = states[entity];
  const state = id => states[id]?.state;
  const boolean = id => ['on', 'off'].includes(state(id));
  const number = value => value !== null && value !== undefined && String(value).trim() !== '' && Number.isFinite(Number(value)) ? Number(value) : null;
  const fmt = value => Number(value.toFixed(1)).toLocaleString('cs-CZ');
  const palette = {
    eco: ['#0f766e', '#5eead4'], schedule: ['#1d4ed8', '#93c5fd'],
    demand: ['#b45309', '#fcd34d'], manual: ['#7e22ce', '#d8b4fe'],
    off: ['#475569', '#cbd5e1'], error: ['#b91c1c', '#fca5a5'],
    unknown: ['#6b21a8', '#d8b4fe']
  };
  let kind = 'unknown';
  let label = 'Režim neznámý';
  let expected = null;
  const target = number(e?.attributes?.temperature);
  const requestState = state('binary_sensor.zona_' + z + '_aktivni');
  const demand = number(state('sensor.zona_' + z + '_demand'));
  const alive = state('binary_sensor.heating_valve_' + z + '_alive');
  const ready = e && !['unknown', 'unavailable', ''].includes(e.state) && alive === 'on';
  const requestKnown = ready && ['on', 'off'].includes(requestState) && demand !== null && demand >= 0 && demand <= 100;
  let request = 'Žádá kotel: neznámo';
  if (requestKnown) request = requestState === 'on' ? 'Žádá kotel: ano · ' + fmt(demand) + ' %' : 'Žádá kotel: ne';
  const mode = state('input_select.topny_rezim');
  const enabled = state('input_boolean.topny_system_enable');
  const dispatch = state('input_boolean.heating_central_dispatch_enable');
  const guard = state('input_boolean.heating_startup_reconcile_guard');
  const manual = state('input_boolean.' + z + '_manual_override');
  const manualType = state('input_select.' + z + '_manual_override_type');
  const timer = state('timer.' + z + '_manual_override');
  const schedule = state('input_boolean.' + z + '_schedule_active');
  const boost = state('binary_sensor.kotel_boost_active');
  const eco = number(state('input_number.eco_temp_default'));
  const comfort = number(state('input_number.' + z + '_last_comfort'));
  const offset = number(state('input_number.boost_comfort_offset_c'));
  const manualKnown = ['on', 'off'].includes(manual) && (manual === 'off' || manualType === 'Do další změny rozvrhu' || (manualType === 'Časovač' && ['active', 'idle', 'paused'].includes(timer)));
  const manualEffective = manual === 'on' && (manualType === 'Do další změny rozvrhu' || (manualType === 'Časovač' && timer === 'active'));
  if (!e || e.state === 'unknown' || e.state === '') label = 'Hlavice: neznámý stav';
  else if (e.state === 'unavailable') { label = 'Hlavice nedostupná'; kind = 'error'; }
  else if (alive !== 'on') { label = 'Hlavice: chybí čerstvá data'; kind = 'error'; }
  else if (e.state === 'off') { label = 'Hlavice vypnutá'; kind = 'off'; }
  else if (enabled === 'off') { label = 'Řízení vypnuté'; kind = 'off'; }
  else if (mode === 'Off') { label = 'Režim Off'; kind = 'off'; }
  else if (dispatch === 'off') { label = 'Automatické řízení vypnuté'; kind = 'off'; }
  else if (guard === 'on') { label = 'Spouštění řízení'; kind = 'schedule'; }
  else if (enabled !== 'on' || dispatch !== 'on' || guard !== 'off' || !['Auto', 'Eco', 'Boost'].includes(mode) || !manualKnown || !boolean('binary_sensor.kotel_boost_active')) {
    label = 'Režim: chybí data';
  } else if (manualEffective) { label = 'Manuál'; kind = 'manual'; expected = comfort ?? eco; }
  else if (boost === 'on') { label = 'Boost'; kind = 'demand'; expected = (comfort ?? eco) !== null && offset !== null ? (comfort ?? eco) + offset : null; }
  else if (mode === 'Eco') { label = 'Útlum'; kind = 'eco'; expected = eco; }
  else if (schedule === 'on') { label = 'Rozvrh aktivní'; kind = 'schedule'; expected = comfort ?? eco; }
  else if (schedule === 'off') { label = 'Útlum'; kind = 'eco'; expected = eco; }
  else label = 'Rozvrh: chybí data';

  const min = number(e?.attributes?.min_temp) ?? 5;
  const max = number(e?.attributes?.max_temp) ?? 30;
  if (expected !== null) expected = Math.max(min, Math.min(max, expected));
  const lines = [label + (target !== null ? ' · ' + fmt(target) + ' °C' : ''), request];
  if (requestKnown && requestState === 'on' && !['error', 'unknown'].includes(kind)) kind = 'demand';
  if (!requestKnown && !['error', 'unknown'].includes(kind)) kind = 'unknown';
  const adaptation = states['sensor.' + z + '_stav_adaptacniho_behu']?.attributes?.In_progress;
  if (ready && adaptation === true) { lines.push('Probíhá adaptace'); if (kind !== 'error') kind = 'schedule'; }
  if (ready && target === null) { lines.push('Cílová teplota neznámá'); kind = 'unknown'; }
  if (ready && expected !== null && target !== null && Math.abs(expected - target) > 0.100001) {
    lines.push('Čeká na cíl ' + fmt(expected) + ' °C'); kind = 'error';
  }
  return {lines, color: palette[kind][0], ink: palette[kind][hass.themes?.darkMode ? 1 : 0], kind};
};
  const status = getStatus(hass, entity);
  const rgb = [1, 3, 5].map(i => parseInt(status.color.slice(i, i + 2), 16)).join(',');
  const caption = status.lines.map(line => JSON.stringify(line)).join(' "\\A " ');
  return '.bubble-climate-container { --zone-rgb-value: ' + rgb + '; --zone-ink: ' + status.ink + '; --zone-caption: ' + caption + '; }';
})()}
